#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

using namespace std;

/**
 * Problem: 2015-08 - Climbing Stairs
 * 
 * 解題思路：
 * 1. 到達第 n 階的方法數 = 到達第 n-1 階的方法數 (再走 1 步) + 到達第 n-2 階的方法數 (再走 2 步)。
 * 2. 這是典型的費氏數列 (Fibonacci sequence)：f(n) = f(n-1) + f(n-2)。
 * 3. 初始條件：f(1) = 1, f(2) = 2。
 * 4. 注意：當 n 到達 100 時，結果會非常大，超過 64 位整數的範圍。
 * 5. 需要實現大數加法來計算答案。
 */

string add(string a, string b) {
    string res = "";
    int i = a.size() - 1, j = b.size() - 1, carry = 0;
    while (i >= 0 || j >= 0 || carry) {
        int sum = carry + (i >= 0 ? a[i--] - '0' : 0) + (j >= 0 ? b[j--] - '0' : 0);
        res += (sum % 10) + '0';
        carry = sum / 10;
    }
    reverse(res.begin(), res.end());
    return res;
}

int main() {
    vector<string> f(101);
    f[1] = "1";
    f[2] = "2";
    for (int i = 3; i <= 100; i++) {
        f[i] = add(f[i - 1], f[i - 2]);
    }

    int n;
    while (cin >> n) {
        cout << f[n] << endl;
    }
    return 0;
}
